#!/usr/bin/env bash
# Symphony Agent Context Trimmer - Automatic Shell Hook
# Add this snippet to your ~/.bashrc or ~/.zshrc

trim_context() {
  local target="$1"
  if [ -f "$target" ]; then
    npx @symphony/agent-context-trimmer --file "$target" --inplace
  fi
}

claude() {
  # Auto-trim staged prompts before launching claude
  if [ -f "PROMPT.md" ]; then trim_context "PROMPT.md"; fi
  if [ -f ".cursorrules" ]; then trim_context ".cursorrules"; fi
  command claude "$@"
}

aider() {
  # Auto-trim staged prompts before launching aider
  if [ -f "PROMPT.md" ]; then trim_context "PROMPT.md"; fi
  if [ -f ".cursorrules" ]; then trim_context ".cursorrules"; fi
  command aider "$@"
}

cursor() {
  # Auto-trim staged prompts before launching cursor
  if [ -f "PROMPT.md" ]; then trim_context "PROMPT.md"; fi
  if [ -f ".cursorrules" ]; then trim_context ".cursorrules"; fi
  command cursor "$@"
}

# End Symphony Hook
